import React, { useState, useMemo, useEffect } from 'react';
import { useSisreq } from '../context/SisreqContext';
import { RequestCard } from './RequestCard';
import { Status, Area, UserRole, Priority } from '../types';
import { 
    Search, Inbox, GitPullRequest, PlayCircle, CheckCircle2, 
    ChevronDown, LayoutGrid, ShieldAlert, FileStack, List, 
    Table, Clock, User, Building2, MapPin, AlertCircle, Eye,
    Hash, Filter, ArrowRightLeft
} from 'lucide-react';
import { PRIORITY_STYLES, STATUS_BADGE_COLORS } from '../constants';

type DisplayMode = 'kanban' | 'list';

export const Board: React.FC = () => {
  const { 
    requests, 
    updateStatus, 
    globalFilterArea, 
    setGlobalFilterArea, 
    activeRole, 
    canUserSeeRequest, 
    setSelectedRequestId 
  } = useSisreq();

  const [dragOverColumn, setDragOverColumn] = useState<Status | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [errorToast, setErrorToast] = useState<string | null>(null);
  const [displayMode, setDisplayMode] = useState<DisplayMode>('kanban');
  const [isTransitioning, setIsTransitioning] = useState(false);

  // Efecto de transición para cambio de modo
  const handleModeSwitch = (mode: DisplayMode) => {
    if (mode === displayMode) return;
    setIsTransitioning(true);
    setTimeout(() => {
        setDisplayMode(mode);
        setIsTransitioning(false);
    }, 200);
  };

  const filteredRequests = useMemo(() => {
    return requests.filter(req => {
      if (!canUserSeeRequest(req)) return false;

      const term = searchTerm.toLowerCase();
      const matchesSearch = searchTerm === '' || 
          req.title.toLowerCase().includes(term) ||
          req.id.toLowerCase().includes(term) ||
          req.requester.toLowerCase().includes(term) ||
          (req.assignedAnalyst && req.assignedAnalyst.toLowerCase().includes(term));

      const matchesArea = globalFilterArea === 'ALL' || req.area === globalFilterArea;
      return matchesSearch && matchesArea;
    });
  }, [requests, searchTerm, globalFilterArea, canUserSeeRequest]);

  const handleDrop = async (e: React.DragEvent, targetStatus: Status) => {
    e.preventDefault();
    setDragOverColumn(null);
    const requestId = e.dataTransfer.getData('requestId');

    const req = requests.find(r => r.id === requestId);
    if (!req) return;

    if (req.status === targetStatus) return;

    try {
        await updateStatus(requestId, targetStatus);
    } catch (err: any) {
        setErrorToast(err.message);
        setTimeout(() => setErrorToast(null), 4000);
    }
  };

  const COLUMNS = [
    { title: 'Bandeja Central', status: Status.RECIBIDO, icon: <Inbox size={18} strokeWidth={2.5}/>, color: 'bg-indigo-600', text: 'text-indigo-600', light: 'bg-indigo-50' },
    { title: 'Derivación', status: Status.DERIVACION, icon: <GitPullRequest size={18} strokeWidth={2.5}/>, color: 'bg-orange-500', text: 'text-orange-600', light: 'bg-orange-50' },
    { title: 'Ejecución', status: Status.EJECUCION, icon: <PlayCircle size={18} strokeWidth={2.5}/>, color: 'bg-amber-500', text: 'text-amber-600', light: 'bg-amber-50' },
    { title: 'Finalizado', status: Status.FINALIZADO, icon: <CheckCircle2 size={18} strokeWidth={2.5}/>, color: 'bg-emerald-600', text: 'text-emerald-600', light: 'bg-emerald-50' }
  ];

  const isAdminOrSuper = activeRole === UserRole.SUPERADMIN || activeRole === UserRole.ADMIN;

  return (
    <div className="flex flex-col h-full relative overflow-hidden bg-[#F8FAFC]">
      {errorToast && (
          <div className="absolute top-20 left-1/2 -translate-x-1/2 z-[100] bg-red-600 text-white px-6 py-4 rounded-2xl shadow-2xl flex items-center gap-3 animate-in slide-in-from-top-4 duration-300">
              <ShieldAlert size={20} />
              <span className="text-[11px] font-black uppercase tracking-widest">{errorToast}</span>
          </div>
      )}

      {/* Modern Header with Enhanced Controls */}
      <div className="px-8 py-6 flex flex-col gap-6 bg-white border-b border-slate-200 z-20 shadow-sm transition-all">
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="flex items-center gap-5">
                 <div className="bg-slate-900 p-3 rounded-2xl text-white shadow-xl shadow-slate-200">
                    <FileStack size={22} strokeWidth={2.5}/>
                 </div>
                 <div className="flex flex-col">
                     <div className="flex items-center gap-2 mb-1">
                        <span className="bg-indigo-50 text-indigo-600 px-2.5 py-1 rounded-lg text-[9px] font-black border border-indigo-100 uppercase tracking-widest">
                            FLUJO OPERATIVO
                        </span>
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                     </div>
                     <h2 className="text-2xl font-black text-slate-900 tracking-tighter uppercase leading-none">Sistema de Requerimientos</h2>
                 </div>
              </div>

              <div className="flex items-center gap-4">
                 {/* Integrated Search */}
                 <div className="relative group">
                    <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors"/>
                    <input 
                        type="text" 
                        value={searchTerm} 
                        onChange={(e) => setSearchTerm(e.target.value)} 
                        placeholder="ID, Título o Solicitante..." 
                        className="w-full min-w-[280px] pl-12 pr-4 py-3 text-sm font-bold bg-slate-50 border border-slate-200 rounded-2xl focus:bg-white focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-600 outline-none transition-all placeholder:text-slate-300 shadow-inner"
                    />
                 </div>

                 {/* Display Mode Toggle with Animation Effect */}
                 <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200 shrink-0 shadow-inner">
                    <button 
                      onClick={() => handleModeSwitch('kanban')}
                      className={`p-2.5 rounded-xl transition-all duration-300 ${displayMode === 'kanban' ? 'bg-white text-indigo-600 shadow-md ring-1 ring-black/5' : 'text-slate-400 hover:text-slate-600'}`}
                      title="Vista Tablero"
                    >
                      <LayoutGrid size={18} strokeWidth={2.5}/>
                    </button>
                    <button 
                      onClick={() => handleModeSwitch('list')}
                      className={`p-2.5 rounded-xl transition-all duration-300 ${displayMode === 'list' ? 'bg-white text-indigo-600 shadow-md ring-1 ring-black/5' : 'text-slate-400 hover:text-slate-600'}`}
                      title="Vista Lista"
                    >
                      <List size={18} strokeWidth={2.5}/>
                    </button>
                 </div>
              </div>
          </div>

          {/* Enhanced Jurisdictional Unit Filters for Admins */}
          {isAdminOrSuper && (
             <div className="flex flex-wrap items-center gap-3 animate-in slide-in-from-left-2 duration-500">
                <div className="flex items-center gap-2 text-slate-400 mr-2">
                    <Filter size={14} className="opacity-50" />
                    <span className="text-[9px] font-black uppercase tracking-widest">Filtrar por Unidad:</span>
                </div>
                <button 
                    onClick={() => setGlobalFilterArea('ALL')}
                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all ${globalFilterArea === 'ALL' ? 'bg-slate-900 text-white border-slate-900 shadow-lg shadow-slate-200' : 'bg-white text-slate-400 border-slate-200 hover:border-slate-400'}`}
                >
                    Jurisdicción Global
                </button>
                {Object.values(Area).map(a => (
                    <button
                        key={a}
                        onClick={() => setGlobalFilterArea(a)}
                        className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all flex items-center gap-2 ${globalFilterArea === a ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg shadow-indigo-100' : 'bg-white text-slate-400 border-slate-200 hover:border-indigo-200'}`}
                    >
                        <div className={`w-1.5 h-1.5 rounded-full ${globalFilterArea === a ? 'bg-white' : 'bg-slate-300'}`}></div>
                        {a}
                    </button>
                ))}
             </div>
          )}
      </div>

      {/* Main Container with Fluid Transition */}
      <div className={`flex-1 overflow-hidden transition-all duration-300 ${isTransitioning ? 'opacity-0 scale-95' : 'opacity-100 scale-100'}`}>
          {displayMode === 'kanban' ? (
              <div className="h-full overflow-x-auto overflow-y-hidden hide-scrollbar animate-in fade-in slide-in-from-right-4 duration-500">
                  <div className="h-full flex px-8 py-10 gap-8 min-w-[1300px]">
                      {COLUMNS.map((col) => {
                          if (col.status === Status.RECIBIDO && activeRole !== UserRole.ADMIN && activeRole !== UserRole.SUPERADMIN) return null;

                          const items = filteredRequests.filter(r => r.status === col.status);
                          const isDragActive = dragOverColumn === col.status;

                          return (
                              <div 
                                  key={col.status} 
                                  className={`flex-1 flex flex-col min-w-[300px] max-w-[380px] rounded-[2.5rem] transition-all duration-300 ${isDragActive ? 'bg-indigo-50/50 shadow-2xl ring-4 ring-indigo-500/5 scale-[1.02]' : 'bg-transparent'}`} 
                                  onDragOver={(e) => { e.preventDefault(); setDragOverColumn(col.status); }} 
                                  onDragLeave={() => setDragOverColumn(null)} 
                                  onDrop={(e) => handleDrop(e, col.status)}
                              >
                                  <div className="flex items-center justify-between px-6 py-4 bg-white border border-slate-200 rounded-3xl mb-6 shadow-sm group">
                                      <div className="flex items-center gap-4">
                                          <div className={`p-2.5 rounded-2xl text-white shadow-lg transition-transform group-hover:rotate-12 ${col.color}`}>{col.icon}</div>
                                          <div className="flex flex-col">
                                              <span className="text-[11px] font-black uppercase tracking-widest text-slate-800">{col.title}</span>
                                              <span className={`text-[8px] font-black uppercase tracking-[0.2em] ${col.text}`}>FASE OPERATIVA</span>
                                          </div>
                                      </div>
                                      <span className="bg-slate-100 text-slate-500 px-3 py-1 rounded-xl text-[11px] font-black border border-slate-200">{items.length}</span>
                                  </div>

                                  <div className="flex-1 overflow-y-auto px-1 pb-20 hide-scrollbar space-y-5">
                                      {items.map(req => <RequestCard key={req.id} data={req} />)}
                                      {items.length === 0 && (
                                          <div className="flex flex-col items-center justify-center h-48 border-4 border-dashed border-slate-200 rounded-[2.5rem] text-slate-300 opacity-50 bg-white/30 transition-all hover:bg-white/50">
                                              <Inbox size={32} className="mb-2" />
                                              <p className="text-[10px] font-black uppercase tracking-widest">Sin expedientes</p>
                                          </div>
                                      )}
                                  </div>
                              </div>
                          )
                      })}
                  </div>
              </div>
          ) : (
              /* INSTITUTIONAL LIST VIEW with Slide-up Animation */
              <div className="h-full overflow-y-auto custom-scrollbar p-8 animate-in fade-in slide-in-from-bottom-6 duration-500">
                  <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-2xl shadow-slate-200/50 overflow-hidden flex flex-col min-w-[1000px]">
                      {/* Institutional Table Header */}
                      <div className="grid grid-cols-[80px_1fr_120px_120px_140px_140px_100px_60px] gap-4 px-10 py-7 bg-slate-50/80 border-b border-slate-100 text-[9px] font-black text-slate-400 uppercase tracking-[0.15em] items-center">
                          <div><Hash size={12} className="inline mr-1 text-slate-300"/> ID</div>
                          <div><FileStack size={12} className="inline mr-1 text-slate-300"/> Expediente Técnico</div>
                          <div><MapPin size={12} className="inline mr-1 text-slate-300"/> Área</div>
                          <div><Building2 size={12} className="inline mr-1 text-slate-300"/> Solicitante</div>
                          <div><GitPullRequest size={12} className="inline mr-1 text-slate-300"/> Fase Actual</div>
                          <div><User size={12} className="inline mr-1 text-slate-300"/> Responsable</div>
                          <div><AlertCircle size={12} className="inline mr-1 text-slate-300"/> Urgencia</div>
                          <div className="text-right">Detalle</div>
                      </div>

                      {/* Institutional Body Rows */}
                      <div className="divide-y divide-slate-50">
                          {filteredRequests.length > 0 ? filteredRequests.map((req) => (
                              <div 
                                  key={req.id} 
                                  onClick={() => setSelectedRequestId(req.id)}
                                  className="grid grid-cols-[80px_1fr_120px_120px_140px_140px_100px_60px] gap-4 px-10 py-6 items-center hover:bg-indigo-50/40 transition-all group cursor-pointer border-l-4 border-transparent hover:border-indigo-600"
                              >
                                  <div className="text-[10px] font-mono font-black text-slate-400 uppercase group-hover:text-indigo-600 transition-colors">
                                      #{req.id.split('-')[1]?.toUpperCase()}
                                  </div>

                                  <div className="min-w-0">
                                      <div className="flex items-center gap-2 mb-1">
                                          {req.isReturned && (
                                              <span className="text-[7px] bg-red-600 text-white px-1.5 py-0.5 rounded-md font-black uppercase animate-pulse shrink-0 tracking-tighter shadow-sm">RETORNO</span>
                                          )}
                                          <div className="text-[12px] font-black text-slate-800 uppercase truncate group-hover:text-indigo-600 transition-colors tracking-tight">
                                              {req.title}
                                          </div>
                                      </div>
                                      <div className="text-[9px] text-slate-400 font-bold truncate italic opacity-70">
                                          "{req.detail.substring(0, 80)}..."
                                      </div>
                                  </div>

                                  <div>
                                      <span className="text-[9px] font-black text-indigo-600 bg-indigo-50/50 px-2.5 py-1 rounded-lg border border-indigo-100 uppercase tracking-tight">
                                          {req.area}
                                      </span>
                                  </div>

                                  <div className="text-[10px] font-bold text-slate-500 truncate uppercase">
                                      {req.requester}
                                  </div>

                                  <div>
                                      <span className={`px-2.5 py-1.5 rounded-lg text-[8px] font-black uppercase tracking-widest border shadow-sm transition-all ${STATUS_BADGE_COLORS[req.status]}`}>
                                          {req.status}
                                      </span>
                                  </div>

                                  <div className="min-w-0">
                                      {req.assignedAnalyst ? (
                                          <div className="flex items-center gap-2">
                                              <div className="w-7 h-7 rounded-xl bg-slate-800 text-white flex items-center justify-center font-black text-[9px] shrink-0 shadow-md">
                                                  {req.assignedAnalyst.substring(0,2).toUpperCase()}
                                              </div>
                                              <span className="text-[11px] font-black text-slate-700 truncate uppercase tracking-tight">{req.assignedAnalyst.split(' ')[0]}</span>
                                          </div>
                                      ) : (
                                          <span className="text-[9px] text-slate-300 font-black uppercase italic tracking-tighter bg-slate-50 px-2 py-1 rounded-lg border border-slate-100">Sin Asignar</span>
                                      )}
                                  </div>

                                  <div>
                                      <span className={`text-[8px] font-black px-2.5 py-1.5 rounded-lg border transition-all uppercase tracking-widest shadow-sm ${PRIORITY_STYLES[req.priority]}`}>
                                          {req.priority}
                                      </span>
                                  </div>

                                  <div className="flex justify-end">
                                      <div className="p-3 text-slate-300 group-hover:text-indigo-600 transition-all bg-white rounded-2xl border border-transparent group-hover:border-indigo-100 group-hover:shadow-lg">
                                          <Eye size={18} strokeWidth={2.5}/>
                                      </div>
                                  </div>
                              </div>
                          )) : (
                              <div className="p-32 text-center flex flex-col items-center gap-6">
                                  <div className="bg-slate-50 p-10 rounded-[4rem] border border-dashed border-slate-200">
                                      <Inbox size={56} className="text-slate-200"/>
                                  </div>
                                  <div className="space-y-1">
                                      <p className="text-sm font-black text-slate-400 uppercase tracking-[0.2em]">Bandeja Técnica Vacía</p>
                                      <p className="text-[9px] text-slate-300 font-bold uppercase">No hay expedientes bajo los filtros actuales</p>
                                  </div>
                              </div>
                          )}
                      </div>
                  </div>
              </div>
          )}
      </div>
    </div>
  );
};
